import { emit } from "@/lib/event-bus";
import { assertCan } from "@/lib/permissions";
import { isArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as memberRepo from "@/server/repositories/member-repository";
import { hasRoleAtLeast } from "@/types/member";
import { actorEnvelope, memberResource, NotFoundError, requireFound } from "./_support";
import type {
  ListMembersInput,
  RemoveMemberInput,
  UpdateMemberRoleInput,
} from "@/schemas/member";
import type { MemberId, OrgId, Page, UserId } from "@/types/common";
import type { Actor, Member, MemberWithUser, Role } from "@/types/member";

/** How many members are scanned when counting the remaining owners. */
const OWNER_SCAN_LIMIT = 100;

export type SuspendMemberInput = { orgId: OrgId; memberId: MemberId };
export type ReinstateMemberInput = { orgId: OrgId; memberId: MemberId };

/** Thrown when work is handed to a suspended member: issue creation and assignment. */
export class MemberSuspendedError extends Error {
  readonly code = "conflict" as const;

  constructor(readonly memberId: MemberId) {
    super(`Member ${memberId} is suspended and cannot be handed new work`);
    this.name = "MemberSuspendedError";
