  await assertLastOwnerRetained(input.orgId, input.memberId, input.role);

  const updated = await memberRepo.updateMemberRole(
    input.orgId,
    input.memberId,
    input.role,
  );

  await emit("member.role_changed", {
    ...actorEnvelope(actor),
    memberId: updated.id,
    from: member.role,
    to: updated.role,
  });

  return updated;
}

/**
 * Removal is a soft delete, and it is subject to the same last-owner rule as a
 * demotion — a removed owner is a demotion to "no role at all".
 */
export async function removeMember(
  actor: Actor,
  input: RemoveMemberInput,
): Promise<Member> {
  assertOrgScope(actor, input.orgId);

  const member = requireFound(
    await memberRepo.findMemberById(input.orgId, input.memberId),
    "Member",
    input.memberId,
  );
  assertCan(actor, "member:remove", memberResource(member));

  await assertLastOwnerRetained(input.orgId, input.memberId, "member");

  const removed = await memberRepo.archiveMember(input.orgId, input.memberId);

  await emit("member.removed", {
    ...actorEnvelope(actor),
    memberId: removed.id,
    userId: removed.userId,
  });

  return removed;
}

/**
 * Locks a member out without removing them: they keep their membership, role
 * and seat, but can no longer act, receive notifications or new work. Subject
 * to the same guards as removal, plus the rule that nobody may suspend
 * themselves or someone who outranks them.
 */
export async function suspendMember(
  actor: Actor,
  input: SuspendMemberInput,
): Promise<Member> {
  assertOrgScope(actor, input.orgId);

  const member = requireFound(
    await memberRepo.findMemberById(input.orgId, input.memberId),
    "Member",
    input.memberId,
  );
  if (isArchived(member)) {
    throw new NotFoundError("Member", input.memberId);
  }
  assertCan(actor, "member:remove", memberResource(member));

  if (member.userId === actor.userId) {
    throw new Error("You cannot suspend yourself");
  }
  if (!hasRoleAtLeast(actor.role, member.role)) {
    throw new Error(`A ${actor.role} cannot suspend a ${member.role}`);
  }

  if (member.status === "suspended") return member;

  await assertLastOwnerRetained(input.orgId, input.memberId, "member");

  const suspended = await memberRepo.setMemberStatus(
    input.orgId,
    input.memberId,
    "suspended",
  );

  await emit("member.suspended", {
    ...actorEnvelope(actor),
    memberId: suspended.id,
    userId: suspended.userId,
  });

  return suspended;
}

/** Reverses a suspension. Same guards as `suspendMember`, mirrored. */
export async function reinstateMember(
  actor: Actor,
  input: ReinstateMemberInput,
): Promise<Member> {
  assertOrgScope(actor, input.orgId);

  const member = requireFound(
    await memberRepo.findMemberById(input.orgId, input.memberId),
    "Member",
    input.memberId,
  );
  if (isArchived(member)) {
    throw new NotFoundError("Member", input.memberId);
  }
  assertCan(actor, "member:remove", memberResource(member));

  if (member.userId === actor.userId) {
    throw new Error("You cannot reinstate yourself");
  }
  if (!hasRoleAtLeast(actor.role, member.role)) {
    throw new Error(`A ${actor.role} cannot reinstate a ${member.role}`);
  }

  if (member.status !== "suspended") return member;

  const reinstated = await memberRepo.setMemberStatus(
    input.orgId,
    input.memberId,
    "active",
  );

  await emit("member.reinstated", {
    ...actorEnvelope(actor),
    memberId: reinstated.id,
    userId: reinstated.userId,
  });

  return reinstated;
}

/**
 * Turns a (user, org) pair into the `Actor` every service method takes. The
 * only place an `Actor` is minted from stored state — jobs and the session
 * layer both come through here.
 */
export async function resolveActor(
  userId: UserId,
  orgId: OrgId,
): Promise<Actor | null> {
  const member = await memberRepo.findMember(orgId, userId);
  if (!member || member.status !== "active") return null;

  return { userId, orgId, role: member.role };
}

/**
 * Throws when applying `nextRole` to `memberId` would leave the organization
 * without an owner. Exported because both the demote and the remove path need
 * it, and the invariant must not be stated twice.
 */
export async function assertLastOwnerRetained(
  orgId: OrgId,
  memberId: MemberId,
  nextRole: Role,
): Promise<void> {
  if (nextRole === "owner") return;

  const member = await memberRepo.findMemberById(orgId, memberId);
  if (!member || member.role !== "owner") return;

  const page = await memberRepo.listMembers({
    orgId,
    role: "owner",
    limit: OWNER_SCAN_LIMIT,
    cursor: null,
  });

  const remaining = page.items.filter((row) => row.id !== memberId);
  if (remaining.length === 0) {
    throw new Error(
      "An organization must keep at least one owner; transfer ownership first",
    );
  }
}

